    },
    {
      "card_ids": ["C39"],
      "claim": "Isoniazid, a small polar hydrazide, had 93% absolute bioavailability in fasted TB patients, indicating that polar amide-like small molecules can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Imatinib, a larger basic amine drug, has approximately 98% absolute oral bioavailability, supporting high F for basic amine-containing compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Molsidomine, a morpholine-containing small molecule, had 44 ± 15% absolute bioavailability, still well above the 20% threshold and consistent with a high prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence from structurally related molecules reports oral bioavailability well above 20% (44–100%), including fasted-state measurements; combined with favorable physicochemical properties, the query is predicted to have high absolute oral bioavailability (F ≥ 20%).",
